use std::{env, error::Error, fs};

use ga_domain::event_schema::CustomDefinition;
use serde_json::{Value, json};

#[test]
#[ignore = "requires the synthetic fixture generated by the pinned Python contract model"]
fn matches_python_definition_validation_hash_and_defaults() -> Result<(), Box<dyn Error>> {
    let examples: Vec<(Value, Value)> =
        serde_json::from_slice(&fs::read(env::var("GA_TEST_CUSTOM_DEFINITIONS")?)?)?;
    for (index, (input, expected)) in examples.into_iter().enumerate() {
        let computed = match CustomDefinition::from_json(&input) {
            Ok(contract) => json!([contract.key(), contract.hash(), contract.contract()]),
            Err(_) => Value::Null,
        };
        assert_eq!(computed, expected, "custom definition {index}");
    }
    Ok(())
}
